def find_largest_palindromic_cube(N: int) -> int:
    index = 1
    largest_palindrome = 0
    while True:
        three = index * index * index
        if three > N:
            break
        strthree = str(three)
        if strthree == strthree[::-1]:
            largest_palindrome = three
        index += 1
    return largest_palindrome
